// Arma una sola consulta con todas las ofertas.
// Los datos viajan como parámetro JSON ($1), no dentro del texto SQL:
// así los signos $ de los sueldos no rompen nada.
//
// El pipeline es comun a todos los usuarios: la tabla jobs ya no tiene user_id.
// El estado por usuario (guardado, aplicado, notas, sueldo pretendido) vive en
// user_jobs y lo escribe la app, no este nodo.

const txt = v => (v === null || v === undefined || v === '' ? null : String(v));
const num = v => {
  if (v === null || v === undefined || v === '') return null;
  const x = Number(v);
  return Number.isFinite(x) ? Math.round(x) : null;
};

const ids = new Set();
const pairs = new Set();
const rows = [];

for (const item of $input.all()) {
  const o = item.json;
  if (!o.job_id || !o.apply_url) continue;
  const pair = `${String(o.company).toLowerCase().trim()}|${String(o.title).toLowerCase().trim()}`;
  if (ids.has(o.job_id) || pairs.has(pair)) continue; // duplicados dentro de esta corrida
  ids.add(o.job_id);
  pairs.add(pair);

  rows.push({
    external_id: txt(o.job_id),
    title: txt(o.title),
    apply_url: txt(o.apply_url),
    locations: txt(o.locations),
    department: txt(o.department),
    description: txt(o.description),
    published_at: txt(o.published_at),
    priority: num(o.priority) ?? 3,
    role_category: txt(o.role_category) || 'ic',
    accepts_argentina: txt(o.accepts_argentina),
    location_match: txt(o.location_match),
    source: txt(o.source),
    salary: txt(o.salary),
    salary_max_k: num(o.salary_max_k),
    company_id: num(o.company_id),
    company: txt(o.company),
    company_slug: txt(o.company_slug),
    company_hq: txt(o.company_hq),
    company_size: num(o.company_size),
    company_stage: txt(o.company_stage),
    company_linkedin: txt(o.company_linkedin),
    linkedin_people_ar: txt(o.linkedin_people_ar),
  });
}

const sql = `
INSERT INTO jobs (
  external_id, title, apply_url, locations, department, description, published_at, priority,
  role_category, accepts_argentina, location_match, source, salary, salary_max_k,
  company_id, company, company_slug, company_hq, company_size, company_stage,
  company_linkedin, linkedin_people_ar
)
SELECT v.external_id, v.title, v.apply_url, v.locations, v.department, v.description, v.published_at,
       v.priority, v.role_category::role_category, v.accepts_argentina::argentina_fit,
       v.location_match, v.source::job_source, v.salary, v.salary_max_k,
       v.company_id, v.company, v.company_slug, v.company_hq, v.company_size,
       v.company_stage, v.company_linkedin, v.linkedin_people_ar
FROM jsonb_to_recordset($1::jsonb) AS v(
  external_id text, title text, apply_url text, locations text, department text,
  description text, published_at date, priority smallint, role_category text,
  accepts_argentina text, location_match text, source text, salary text, salary_max_k int,
  company_id int, company text, company_slug text, company_hq text, company_size int,
  company_stage text, company_linkedin text, linkedin_people_ar text
)
WHERE NOT EXISTS (
  SELECT 1 FROM jobs j
  WHERE lower(j.company) = lower(v.company)
    AND lower(j.title) = lower(v.title)
    AND j.external_id <> v.external_id
    AND j.closed_at IS NULL
)
ON CONFLICT (external_id) DO UPDATE SET
  last_seen_at   = CURRENT_DATE,
  closed_at = NULL,
  republished_at = CASE WHEN EXCLUDED.published_at IS NOT NULL
                         AND jobs.published_at IS NOT NULL
                         AND EXCLUDED.published_at > jobs.published_at
                        THEN CURRENT_DATE ELSE jobs.republished_at END,
  published_at   = GREATEST(jobs.published_at, EXCLUDED.published_at),
  locations      = EXCLUDED.locations,
  department     = COALESCE(EXCLUDED.department, jobs.department),
  description    = COALESCE(EXCLUDED.description, jobs.description),
  salary         = COALESCE(EXCLUDED.salary, jobs.salary),
  salary_max_k   = COALESCE(EXCLUDED.salary_max_k, jobs.salary_max_k),
  company_hq     = COALESCE(EXCLUDED.company_hq, jobs.company_hq),
  company_size   = COALESCE(EXCLUDED.company_size, jobs.company_size),
  company_id     = COALESCE(EXCLUDED.company_id, jobs.company_id),
  -- La clasificación se recalcula en cada corrida: si cambian las reglas,
  -- las ofertas viejas se corrigen solas en vez de quedar con el veredicto viejo.
  accepts_argentina = EXCLUDED.accepts_argentina,
  location_match    = EXCLUDED.location_match,
  priority          = EXCLUDED.priority,
  role_category     = EXCLUDED.role_category
RETURNING id, external_id, title, department, locations, description, (xmax = 0) AS inserted
`;

const params = JSON.stringify(rows);

console.log('=== BUILD SQL ===');
console.log('filas       : ' + rows.length);
console.log('params (MB) : ' + (params.length / 1048576).toFixed(2));

return [{ json: { sql, params, rows: rows.length } }];

// Trae las ofertas crudas de las empresas que publican en Workday.
// Su API es POST y pagina de a 20, por eso no entra en el nodo HTTP común.
// Las empresas se consultan en paralelo, de a tandas, para que no tarde tanto.
const SEARCH_TERMS = ['engineer', 'developer', 'architect'];
const PAGE_SIZE = 20;      // Workday devuelve vacío si se pide más de 20
const MAX_PAGES = 3;       // tope por término: 60 ofertas
const CONCURRENCY = 12;     // empresas en paralelo
const TIMEOUT_MS = 15000;   // una empresa que no responde no frena la tanda

const http = (opts) => this.helpers.httpRequest(opts);

// teladoc.wd503.myworkdayjobs.com/teladochealth_is_hiring
//   → https://teladoc.wd503.myworkdayjobs.com/wday/cxs/teladoc/teladochealth_is_hiring/jobs
function wdEndpoint(careersUrl) {
  const clean = String(careersUrl || '').replace(/^https?:\/\//, '').replace(/\/+$/, '');
  const parts = clean.split('/');
  const host = parts.shift();
  if (!host || !parts.length) return null;
  const tenant = host.split('.')[0];
  const site = parts[parts.length - 1];
  if (!tenant || !site) return null;
  return {
    api: `https://${host}/wday/cxs/${tenant}/${site}/jobs`,
    jobBase: `https://${host}/${parts.join('/')}`,
  };
}

async function pagesFor(api, term) {
  const found = [];
  for (let page = 0; page < MAX_PAGES; page++) {
    let res;
    try {
      res = await http({
        method: 'POST',
        url: api,
        json: true,
        timeout: TIMEOUT_MS,
        headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
        body: { appliedFacets: {}, limit: PAGE_SIZE, offset: page * PAGE_SIZE, searchText: term },
      });
    } catch (e) {
      break; // empresa que no responde: se saltea
    }
    const list = res?.jobPostings || [];
    found.push(...list);
    if (list.length < PAGE_SIZE) break;
  }
  return found;
}

async function fetchCompany(c) {
  const ep = wdEndpoint(c.careers_url);
  if (!ep) return [];
  const porTermino = await Promise.all(SEARCH_TERMS.map(t => pagesFor(ep.api, t)));
  const vistos = new Map();
  for (const lista of porTermino) {
    for (const j of lista) if (j.externalPath) vistos.set(j.externalPath, j);
  }
  return [...vistos.values()].map(j => ({ json: { company: c, jobBase: ep.jobBase, job: j } }));
}


const env = $('ENV').first().json.env;
const companiesEnvironment = env === 'local'
  ? $('Read Companies LOCAL').all()
  : $('Read Companies PROD').all();

const empresas = companiesEnvironment
  .map(i => i.json)
  .filter(c => (c.ats || '').toLowerCase() === 'workday' && c.careers_url);

const out = [];
for (let i = 0; i < empresas.length; i += CONCURRENCY) {
  const tanda = await Promise.all(empresas.slice(i, i + CONCURRENCY).map(fetchCompany));
  for (const r of tanda) out.push(...r);
}

return out;

// Get on Board: portal de empleo de LATAM, API pública y gratuita.
const http = (opts) => this.helpers.httpRequest(opts);

const CATEGORIES = [
  'programming',
  'data-science-analytics',
  'machine-learning-ai',
  'sysadmin-devops-qa',
  'mobile-developer',
];
const PER_PAGE = 100;
const MAX_PAGES = 6;

const out = [];

for (const cat of CATEGORIES) {
  for (let page = 1; page <= MAX_PAGES; page++) {
    let res;
    try {
      res = await http({
        method: 'GET',
        url: `https://www.getonbrd.com/api/v0/categories/${cat}/jobs`,
        qs: { per_page: PER_PAGE, page },
        json: true,
      });
    } catch (e) {
      break;
    }
    const data = res?.data || [];
    for (const job of data) out.push({ json: { job } });
    const total = res?.meta?.total_pages || 1;
    if (!data.length || page >= total) break;
  }
}

return out;

// =====================================================================
//  Classify & Filter  —  CON INSTRUMENTACION (temporal)
//
//  Cuenta los descartes por motivo y emite un item de resumen al principio.
//  No cambia que avisos pasan: lo que pasaba antes sigue pasando.
//  Para sacarlo despues: borrar las lineas marcadas con  // [INSTR]
// =====================================================================

const MIN_SALARY_K = 60;

const IS_ENGINEERING = /engineer|engineering|developer|desarrollador|desarrollo|programador|programmer|builder|full.?stack|front.?end|back.?end|ingenier|arquitect|\bsre\b|devops|architect|tech(nical)? lead|l[íi]der t[ée]cnico|forward deployed|machine learning|\bml\b|\bcto\b|head of eng|vp.*eng/i;
const IS_ENG_DEPT = /engineer|engineering|technolog|\btech\b|software|\br&?d\b|platform|infrastructur/i;
const EXCLUDE = /recruit|reclut|talent|sales(?! engineer)|ventas|account exec|marketing|designer|dise[ñn]ador|legal|finance|contador|intern|pasant|practicante|product manager|program manager|project manager|gerente de producto|jefe de producto|\banalyst\b|analista(?! programador)|data scientist|cient[íi]fico de datos|incident manager/i;
const EXCLUDE_EVERGREEN = /future .*(opportunit|role|position)|general interest|talent (pool|community|network)|open application|spontaneous/i;

const ARGENTINA = /argentin|buenos aires/i;
const LATAM = /latam|latin america|south america|\bamericas\b/i;
const GLOBAL = /\b(anywhere|worldwide|global)\b/i;
const REMOTE_ONLY = /^(remote|remoto|fully remote)$/i;
const US_ONLY = /(must|need to|required to)\s+(be\s+)?(based|located|live|reside)[^.]{0,40}(united states|u\.s\.|\busa\b)|(authorized|authorization|eligible)\s+to\s+work\s+in\s+the\s+(united states|u\.s\.)|u\.s\.\s+(citizen|work authorization)|citizen\/visa only/i;

const MANAGER = /manager|gerente|jefe|head of|director|\bvp\b|vice president|\bcto\b/i;
const LEAD = /lead|l[íi]der|staff|principal|forward deployed|product engineer|founding/i;
const PRIORITY = { manager: 1, lead_staff: 2, ic: 3 };

const LATAM_COUNTRY = /\b(argentin|brazil|brasil|colombia|chile|uruguay|per[úu]|paraguay|bolivia|ecuador|venezuela|(?<!new )m[ée]xico|costa rica|panam[áa]|guatemala)\b|\b(ARG|BRA|COL|CHL|URY|PER|MEX|CRI)\b|\b(bogot[áa]|medell[íi]n|barranquilla|cartagena|s[ãa]o paulo|rio de janeiro|porto alegre|belo horizonte|curitiba|florian[óo]polis|joinville|recife|montevideo|asunci[óo]n|guadalajara|monterrey|cdmx|quito|guayaquil|san salvador|tegucigalpa|managua)\b/i;
const OTHER_LATAM_CODE = /\b(BR|CO|CL|UY|PE|MX|EC|BO|PY|VE|CR)\b/;
const NY_STREET = /ave(nue)?\.?\s+of\s+(the\s+)?americas/ig;

// "Americas" a secas es ambiguo; "LATAM" y "Latin America" no lo son.
const AMERICAS_GENERIC = /\bamericas\b/i;
const EXPLICIT_LATAM   = /latam|latin america|south america/i;
const NORTH_AM_COUNTRY = /\b(usa|u\.s\.a?\.?|united states|canada|canad[áa])\b/i;
// El titulo nombra EE.UU. aunque la ubicacion diga solo "Remote"
const US_IN_TITLE = /\busa\b|\bu\.s\.a?\.|\bunited states\b/i;

const IGNORED_COMPANIES = ['canonical'];

const MAX_AGE_DAYS = 180;
const CUTOFF = new Date(Date.now() - MAX_AGE_DAYS * 86400000).toISOString().slice(0, 10);

// Las descripciones vienen en HTML crudo y pesan 10-20 KB cada una.
// Se guardan limpias y recortadas: el payload baja ~90% y el modelo
// no paga tokens por etiquetas ni por el boilerplate del final.
const MAX_DESC_CHARS = 4000;
function limpiarDesc(s) {
  if (!s) return '';
  return String(s)
    .replace(/<(script|style)[^>]*>[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#39;|&apos;|&rsquo;/g, "'")
    .replace(/&quot;|&ldquo;|&rdquo;/g, '"')
    .replace(/&#\d+;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, MAX_DESC_CHARS);
}

// ---------------------------------------------------------------------

function classify(rawLoc, extra, title,o) {
  const t = title || '';
  const loc = String(rawLoc || '').replace(NY_STREET, '');

  if (ARGENTINA.test(loc) || /\bARG\b/.test(loc)) return ['yes', 'argentina_in_location'];
  if (/\bAR\b/.test(loc) && OTHER_LATAM_CODE.test(loc)) return ['yes', 'argentina_in_location'];

  // "Americas (USA or Canada)": nombra la region pero enumera paises de afuera
  if (AMERICAS_GENERIC.test(loc) && NORTH_AM_COUNTRY.test(loc)
      && !EXPLICIT_LATAM.test(loc) && !LATAM_COUNTRY.test(loc)) {
    return ['no', 'descartado_americas_us_ca'];
  }

  if (LATAM.test(loc)) return ['yes', 'latam_in_location'];
  if (ARGENTINA.test(t)) return ['yes', 'argentina_in_title'];
  if (LATAM.test(t)) return ['yes', 'latam_in_title'];

  // "Team Lead, Android Core Product - Boise, ID, USA" con ubicacion "Remote"
  if (US_IN_TITLE.test(t)) return ['no', 'descartado_us_en_titulo'];

  // La bandera viene calculada sobre el texto completo en Normalize.
  // El test sobre `extra` queda de respaldo para las fuentes que todavia
  // no la mandan (Workday, YC, Get on Board).
  const restricted = (o && o.us_only === true) || US_ONLY.test(extra);
  const parts = loc.split(/\s*[|\/;]\s*/).map(p => p.trim()).filter(Boolean);
  const remoteOnly = parts.length > 0 && parts.every(p => REMOTE_ONLY.test(p) || GLOBAL.test(p));

  if (remoteOnly && !restricted) {
    return ((o && o.visa_not_required === true) || /not required/i.test(extra))
      ? ['maybe', 'remote_visa_not_required']
      : ['maybe', 'remote_no_country'];
  }

  if (LATAM_COUNTRY.test(loc) && /remote|remoto|híbrido|hybrid/i.test(loc) && !restricted) {
    return ['maybe', 'latam_country_remote'];
  }

  const hasCountryInfo = parts.some(p => !REMOTE_ONLY.test(p) && !GLOBAL.test(p));
  if (!hasCountryInfo && ((o && o.latam_hint === true) || ARGENTINA.test(extra) || LATAM.test(extra)) && !restricted)  {
    return ['maybe', 'latam_in_description'];
  }

  return ['no', restricted ? 'descartado_us_only_en_descripcion' : 'descartado_sin_senal_latam'];
}

function salaryMaxK(s) {
  const m = (s || '').match(/\$([\d.,]+)\s*(K?)\s*[-–]\s*\$([\d.,]+)\s*(K?)/i);
  if (!m) return null;
  let max = parseFloat(m[3].replace(/,/g, ''));
  if (!m[4]) max = max / 1000;
  return max < 20 ? Math.round(max * 12) : max;
}

function roleCategory(title) {
  if (MANAGER.test(title)) return 'manager';
  if (LEAD.test(title)) return 'lead_staff';
  return 'ic';
}

function guessHq(locations) {
  const count = {};
  for (const raw of locations) {
    for (const p of String(raw || '').split(/\s*[|\/;]\s*/)) {
      const v = p.trim();
      if (!v || /remote|remoto|anywhere|worldwide|global|latam|latin america/i.test(v)) continue;
      count[v] = (count[v] || 0) + 1;
    }
  }
  const top = Object.entries(count).sort((a, b) => b[1] - a[1])[0];
  return top ? top[0] : '';
}

// ---------------------------------------------------------------------
// [INSTR] contadores
const drops = {};
const deptsNoEng = {};
const motivosNoElegible = {};
const bump = (obj, k) => { if (!k) return; obj[k] = (obj[k] || 0) + 1; };
const topN = (obj, n) => Object.entries(obj).sort((a, b) => b[1] - a[1]).slice(0, n)
                               .map(([k, v]) => ({ depto: k, n: v }));
function drop(motivo, o) {
  bump(drops, motivo);
  if (motivo === 'no_es_ingenieria') {
    bump(deptsNoEng, String(o?.department || '').trim().toLowerCase() || '(sin departamento)');
  }
}
// [INSTR] fin

const items = $input.all().map(i => i.json || {});

const locsByCompany = {};
for (const o of items) {
  if (!o.company_slug) continue;
  (locsByCompany[o.company_slug] = locsByCompany[o.company_slug] || []).push(o.locations);
}

const out = [];
const seen = new Set();

for (const o of items) {
  if (!o.job_id) { drop('sin_job_id', o); continue; }                        // [INSTR]
  if (seen.has(o.job_id)) { drop('duplicado_en_corrida', o); continue; }     // [INSTR]
  seen.add(o.job_id);

  const title = String(o.title || '');
  if (!title) { drop('sin_titulo', o); continue; }                           // [INSTR]

  const isEng = IS_ENGINEERING.test(title) || IS_ENG_DEPT.test(o.department || '');
  if (!isEng) { drop('no_es_ingenieria', o); continue; }                     // [INSTR]
  if (EXCLUDE.test(title)) { drop('excluido_por_titulo', o); continue; }     // [INSTR]
  if (EXCLUDE_EVERGREEN.test(title)) { drop('evergreen', o); continue; }     // [INSTR]

  const companyLower = String(o.company || '').trim().toLowerCase();
  if (companyLower && IGNORED_COMPANIES.some(c => companyLower.startsWith(c))) {
    drop('empresa_en_lista_negra', o); continue;                             // [INSTR]
  }

  const pub = String(o.published_at || '');
  if (pub && pub < CUTOFF) { drop('mas_viejo_que_180_dias', o); continue; }  // [INSTR]

  // OJO: classify() recibe la descripcion CRUDA, sin recortar.
  // Con la version recortada se perderian las detecciones de
  // "must be based in the US" que viven al final del texto.
  const [accepts, match] = Array.isArray(o.match_override)
    ? o.match_override
    : classify(o.locations, o.description, title,o);
  if (accepts === 'no') {
    drop('no_elegible_latam', o);                                            // [INSTR]
    bump(motivosNoElegible, match || 'sin_motivo');                          // [INSTR]
    continue;
  }

  const maxK = (o.salary_max_k === '' || o.salary_max_k === null || o.salary_max_k === undefined)
    ? salaryMaxK(o.salary)
    : Number(o.salary_max_k);
  if (maxK !== null && !Number.isNaN(maxK) && maxK < MIN_SALARY_K) {
    drop('salario_bajo', o); continue;                                       // [INSTR]
  }

  const role = roleCategory(title);
  const li = o.company_linkedin || '';

  out.push({ json: {
    job_id: o.job_id,
    company_id: o.company_id ?? '',
    priority: PRIORITY[role],
    role_category: role,
    accepts_argentina: accepts,
    location_match: match,
    company: o.company || '',
    company_slug: o.company_slug || '',
    company_hq: o.company_hq || guessHq(locsByCompany[o.company_slug] || []),
    company_size: o.company_size || '',
    company_stage: o.company_stage || '',
    title: title.trim(),
    department: o.department || '',
    description: limpiarDesc(o.description),
    salary: o.salary || '',
    salary_max_k: (maxK === null || Number.isNaN(maxK)) ? '' : maxK,
    locations: o.locations || '',
    published_at: o.published_at || '',
    apply_url: o.apply_url || '',
    company_linkedin: li,
    linkedin_people_ar: li ? `${li}/people/?facetGeoRegion=100446943` : '',
    source: o.source || '',
    gob_company_id: o.gob_company_id || '',
  }});
}

// [INSTR] resumen como primer item. Muere en "Deduplicate and complete"
// porque no tiene company ni title, asi que no llega a la base.
out.unshift({ json: {
  __RESUMEN__: true,
  entrada: items.length,
  pasaron: out.length,
  descartados: Object.values(drops).reduce((a, b) => a + b, 0),
  descartes_por_motivo: Object.fromEntries(
    Object.entries(drops).sort((a, b) => b[1] - a[1])
  ),
  departamentos_de_los_no_ingenieria: topN(deptsNoEng, 50),
  motivos_no_elegible: Object.fromEntries(
    Object.entries(motivosNoElegible).sort((a, b) => b[1] - a[1])
  ),
}});
// [INSTR] fin

console.log('=== RESUMEN === \n' + JSON.stringify(out[0].json, null, 2));

return out;

// =====================================================================
//  Normalize ATS  — 
//
//  Solo traduce Ashby / Greenhouse / Lever / Workable / Teamtailor al
//  formato comun y resuelve a que empresa pertenece cada aviso.
// =====================================================================

// El texto completo de la descripcion se usa SOLO adentro de este nodo,
// para decidir elegibilidad, y despues se descarta. Lo que viaja al resto
// del pipeline es un recorte corto mas dos banderas con el veredicto ya
// tomado. Con ~50.000 avisos por corrida, llevar el texto entero eran
// cientos de MB sostenidos en memoria y n8n se quedaba sin aire.
const MAX_DESC = 2000;
const cap = s => String(s || '').replace(/\s+/g, ' ').trim().slice(0, MAX_DESC);

// Mismas expresiones que usa Classify & Filter, aplicadas acá sobre el
// texto COMPLETO en vez de sobre el recorte.
const US_ONLY_RE = /(must|need to|required to)\s+(be\s+)?(based|located|live|reside)[^.]{0,40}(united states|u\.s\.|\busa\b)|(authorized|authorization|eligible)\s+to\s+work\s+in\s+the\s+(united states|u\.s\.)|u\.s\.\s+(citizen|work authorization)|citizen\/visa only/i;
const LATAM_HINT_RE = /argentin|buenos aires|latam|latin america|south america|\bamericas\b/i;
const VISA_NOT_REQ_RE = /not required/i;

// Teamtailor: ubicacion estructurada dentro de _jobposting
function ttLocations(jp) {
  const out = [];
  for (const p of jp?.jobLocation || []) {
    const a = p.address || {};
    const v = [a.addressLocality, a.addressRegion, a.addressCountry].filter(Boolean).join(', ');
    if (v) out.push(v);
  }
  return out.join(' | ');
}

function stripHtml(h) {
  return String(h || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"')
    .replace(/\s+/g, ' ').trim();
}

// Greenhouse devuelve el content con las etiquetas escapadas (&lt;p&gt;).
// Se corta a 20000 nada mas para acotar casos patologicos: el recorte real
// lo hace cap(), despues de evaluar las banderas sobre este texto.
function ghContent(s) {
  const decoded = String(s || '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
  return stripHtml(decoded).slice(0, 20000);
}

// El departamento viene con forma distinta en cada plataforma:
// texto, objeto con name, o array
function deptOf(v) {
  if (!v) return '';
  if (typeof v === 'string') return v.trim();
  if (Array.isArray(v)) return deptOf(v[0]);
  return String(v.name || v.title || '').trim();
}

// Plataforma segun la forma de la oferta, no segun el indice del item
function detectAts(j) {
  if (j && j.shortcode && (j.url || j.shortlink)) return 'workable';
  if (j && j._jobposting) return 'teamtailor';
  if (j && j.absolute_url) return 'greenhouse';
  if (j && j.hostedUrl) return 'lever';
  return 'ashby';
}

// Slug de la empresa segun la URL de la oferta
function slugFromUrl(u) {
  const s = String(u || '');
  let m;
  if ((m = s.match(/jobs\.ashbyhq\.com\/([^\/?#]+)/i))) return m[1];
  if ((m = s.match(/greenhouse\.io\/([^\/?#]+)/i))) return m[1];
  if ((m = s.match(/jobs\.lever\.co\/([^\/?#]+)/i))) return m[1];
  if ((m = s.match(/apply\.workable\.com\/([^\/?#]+)/i))) return m[1];
  if ((m = s.match(/https?:\/\/([^.\/]+)\.(?:[a-z]{2}\.)?teamtailor\.com/i))) return m[1];
  return '';
}

// Dominio de una URL, sin "www.".
// Hace falta porque algunas empresas configuran su board para redirigir a su
// propio sitio: Twindo publica en Greenhouse pero sus ofertas quedan en
// https://www.twindo.com/careers/?gh_jid=123, donde no aparece "greenhouse.io".
function hostOf(u) {
  const m = String(u || '').match(/^https?:\/\/([^\/?#]+)/i);
  return m ? m[1].toLowerCase().replace(/^www\./, '') : '';
}

// Convierte una oferta de cualquier plataforma al mismo formato.
// description viene COMPLETA; el recorte se hace mas abajo.
function normalize(ats, j) {
  if (ats === 'workable') {
    const locs = (j.locations || [])
      .map(l => [l.city, l.region, l.country].filter(Boolean).join(', '))
      .filter(Boolean);
    const base = locs.length ? locs.join(' | ') : [j.city, j.state, j.country].filter(Boolean).join(', ');
    return {
      job_id: `wk:${j.shortcode}`,
      title: j.title || '',
      department: deptOf(j.department) || deptOf(j.departments),
      locations: [j.telecommuting ? 'Remote' : null, base].filter(Boolean).join(' | '),
      description: stripHtml(j.description),
      salary: '',
      published_at: String(j.published_on || j.created_at || '').slice(0, 10),
      apply_url: j.url || j.shortlink,
    };
  }
  if (ats === 'teamtailor') {
    const jp = j._jobposting || {};
    return {
      job_id: `tt:${jp.identifier?.value || j.id}`,
      title: j.title || jp.title || '',
      department: deptOf(j.department) || deptOf(jp.department),
      locations: ttLocations(jp),
      description: stripHtml(j.content_html),
      salary: '',
      published_at: String(j.date_published || jp.datePosted || '').slice(0, 10),
      apply_url: j.url,
    };
  }
  if (ats === 'greenhouse') return {
    job_id: `gh:${j.id}`,
    title: j.title || '',
    department: deptOf(j.departments) || deptOf(j.department),
    locations: j.location?.name || '',
    description: ghContent(j.content),
    salary: '',
    published_at: (j.first_published || j.updated_at || '').slice(0, 10),
    apply_url: j.absolute_url,
  };
  if (ats === 'lever') {
    const sr = j.salaryRange;
    return {
      job_id: `lever:${j.id}`,
      title: j.text || '',
      department: deptOf(j.categories?.department) || deptOf(j.categories?.team),
      locations: [...new Set([j.categories?.location, ...(j.categories?.allLocations || [])].filter(Boolean))].join(' | '),
      description: j.descriptionPlain || '',
      salary: sr && sr.max ? `$${Math.round(sr.min / 1000)}K - $${Math.round(sr.max / 1000)}K` : '',
      published_at: j.createdAt ? new Date(j.createdAt).toISOString().slice(0, 10) : '',
      apply_url: j.hostedUrl,
    };
  }
  // Ashby: el pais principal va en location, el resto en secondaryLocations
  return {
    job_id: `ashby:${j.id}`,
    title: j.title || '',
    department: deptOf(j.department) || deptOf(j.team),
    locations: [
      (j.isRemote || j.workplaceType === 'Remote') ? 'Remote' : null,
      j.location,
      ...(j.secondaryLocations || []).map(
        l => l && (l.location || l.address?.postalAddress?.addressCountry)
      ),
    ].filter(Boolean).join(' | '),
    description: j.descriptionPlain || '',
    salary: j.compensation?.scrapeableCompensationSalarySummary || j.compensation?.compensationTierSummary || '',
    published_at: (j.publishedAt || '').slice(0, 10),
    apply_url: j.jobUrl,
  };
}

// ---- Indices de empresas ----
const env = $('ENV').first().json.env;
const companies = env === 'local'
  ? $('Read Companies LOCAL').all()
  : $('Read Companies PROD').all();

const bySlug = new Map();
companies.forEach(it => {
  const c = it.json || {};
