  };
});

// Sin nada que clasificar, no se dispara ninguna query.
if (!rows.length) return [];

// tags y suggested_tags viajan como jsonb y se convierten a text[] del lado de
// Postgres: jsonb_to_recordset no convierte arrays JSON a text[] de forma confiable.
const sql = `
UPDATE jobs j SET
  job_function        = v.job_function,
  level               = v.level,
  tags                = ARRAY(SELECT jsonb_array_elements_text(v.tags)),
  suggested_tags      = ARRAY(SELECT jsonb_array_elements_text(v.suggested_tags)),
