  taxonomy_version    = v.taxonomy_version
FROM jsonb_to_recordset($1::jsonb) AS v(
  db_id            int,
  job_function     text,
  level            text,
  tags             jsonb,
  suggested_tags   jsonb,
  eligible         boolean,
  is_agency        boolean,
  is_evergreen     boolean,
  note             text,
  taxonomy_version smallint
)
WHERE j.id = v.db_id;
`;

const params = JSON.stringify(rows);

console.log('=== UPDATE SQL ===');
console.log('filas a actualizar: ' + rows.length);

return [{ json: { sql, params, rows: rows.length } }];

// Toma la respuesta de Gemini, la valida contra las listas cerradas y la deja
// lista para el UPDATE.
//
// La validacion no es decorativa: el nodo nativo de Gemini no fuerza el esquema,
// asi que un valor fuera de lista es posible. Aca deja de ser silencioso.

const FUNCIONES = ['engineering','product','design','marketing','sales','operations','support','other'];
const NIVELES   = ['junior','mid','senior','staff','lead','manager','director','vp'];
const TAGS      = ['backend','frontend','fullstack','mobile','infra','data','ml','ai','security','qa','sap','salesforce'];

// Cada version del nodo de Gemini envuelve la respuesta distinto, asi que en
// vez de adivinar la ruta, buscamos en profundidad el primer objeto que tenga
// job_function — venga como objeto o como texto JSON adentro de algun campo.
function buscar(v, depth = 0) {
  if (v == null || depth > 8) return null;

  if (typeof v === 'string') {
    const s = v.trim()
      .replace(/^\s*```(?:json)?\s*/i, '')
      .replace(/\s*```\s*$/, '')
      .trim();
    if (!s.startsWith('{')) return null;
    try {
      const o = JSON.parse(s);
      return (o && o.job_function) ? o : null;
    } catch (e) { return null; }
  }

  if (typeof v === 'object') {
    if (v.job_function) return v;
    for (const k of Object.keys(v)) {
      const r = buscar(v[k], depth + 1);
      if (r) return r;
    }
  }
  return null;
}

const respuestas = $input.all();
const entradas   = $('New to classify').all();

const out = [];
const problemas = [];
let sinNivel = 0;

respuestas.forEach((r, i) => {
  const entrada = entradas[i]?.json || {};
  const c = buscar(r.json);

  if (!c) {
    problemas.push(`[${i}] ${entrada.title || '?'} -> no se pudo parsear la respuesta`);
    return;
  }

  const malos = [];

  if (!FUNCIONES.includes(c.job_function)) malos.push(`job_function="${c.job_function}"`);

  // "unknown" es una respuesta legitima: se guarda como NULL, no como texto.
  // Asi el frontend puede tratarlo como "mostralo igual" en vez de excluirlo.
  const nivelOk = c.level === 'unknown' || NIVELES.includes(c.level);
  if (!nivelOk) malos.push(`level="${c.level}"`);
  const level = NIVELES.includes(c.level) ? c.level : null;
  if (level === null) sinNivel++;

  const tags = Array.isArray(c.tags) ? c.tags.filter(t => TAGS.includes(t)) : [];
  const tagsFuera = (Array.isArray(c.tags) ? c.tags : []).filter(t => !TAGS.includes(t));
  if (tagsFuera.length) malos.push(`tags fuera de lista: ${tagsFuera.join(', ')}`);

  // Texto libre: se normaliza pero no se valida contra ninguna lista.
  // Nunca llega a los filtros; solo alimenta la revision mensual.
  const sugeridos = (Array.isArray(c.suggested_tags) ? c.suggested_tags : [])
    .map(t => String(t || '').toLowerCase().trim())
    .filter(t => t && t.length <= 40 && !TAGS.includes(t))
    .slice(0, 3);

  if (malos.length) problemas.push(`[${i}] ${entrada.title || '?'} -> ${malos.join(' · ')}`);

  out.push({ json: {
    db_id: entrada.db_id,
    external_id: entrada.external_id,
    title: entrada.title,
    job_function: FUNCIONES.includes(c.job_function) ? c.job_function : 'other',
    level,
    tags,
    suggested_tags: sugeridos,
    eligible: c.eligible === true,
    is_agency: c.is_agency === true,
    is_evergreen: c.is_evergreen === true,
    note: String(c.note || '').slice(0, 300),
    taxonomy_version: entrada.taxonomy_version ?? 1,
  }});
});

console.log('=== PARSE ===');
console.log('respuestas: ' + respuestas.length + '  ·  parseadas: ' + out.length + '  ·  sin nivel: ' + sinNivel);
console.log(problemas.length ? 'PROBLEMAS:\n  ' + problemas.join('\n  ') : 'sin problemas de formato');
console.log('---');
for (const { json: o } of out) {
  console.log(
    `${(o.job_function || '?').padEnd(12)} ${(o.level || 'unknown').padEnd(9)} ` +
    `[${o.tags.join(',')}]`.padEnd(22) +
    ` elig=${o.eligible ? 'si' : 'NO'}  ${o.title}`
  );
  console.log(`              ↳ ${o.note}` +
    (o.suggested_tags.length ? `   ⟨sugeridos: ${o.suggested_tags.join(', ')}⟩` : ''));
}

return out;

// Arma el pedido de clasificacion para cada aviso nuevo.
// El prompt y las listas cerradas viven aca, en un solo lugar.
//
// El nodo "Classify (Gemini)" lee de este body dos cosas:
//   body.contents[0].parts[0].text        -> el Prompt
//   body.systemInstruction.parts[0].text  -> el System Message
//
// generationConfig y SCHEMA no los usa el nodo nativo de Gemini: quedan armados
// por si migramos a un HTTP Request, donde responseSchema fuerza la salida a
// nivel del modelo en vez de confiar en el prompt.
//
// Las listas son las de taxonomia.md. Si cambian ahi, cambian aca, y hay que
// subir TAXONOMY_VERSION para poder reclasificar lo viejo.
//
// OJO: las listas de level y tags viven en TRES lugares y tienen que decir lo
// mismo: el SYSTEM de abajo, el SCHEMA de abajo, y las constantes NIVELES y
// TAGS del nodo "Parse classification". Si se desincronizan, el modelo devuelve
// un valor valido y el validador lo tira en silencio.

const MODEL = 'gemini-3.5-flash-lite';
const TAXONOMY_VERSION = 1;

const SYSTEM = `You classify job postings for a job board that lists roles which can be filled from Latin America.

Choose values ONLY from the lists below. Never invent a value.

job_function — pick exactly one:
  engineering  software, data engineering, ML engineering, SRE, DevOps, QA, security, architecture
  product      product management, product operations
  design       UX, UI, product design, user research, brand, graphic
  marketing    growth, content, demand generation, brand, SEO, communications
  sales        account executive, SDR, sales engineering, partnerships, account management
  operations   business operations, finance, legal, HR / people, logistics, administration
  support      customer support, customer success, technical support
  other        anything that fits none of the above, including non-tech roles such as
               field work, retail, manufacturing, healthcare, drivers, data labeling

  The words after each function are EXAMPLES, not an exhaustive list. Generalize
  from them: a role that is not listed still belongs to the closest function.

  Management roles belong to the function of the team they manage, NOT to a
  separate management category:
    Engineering Manager  -> job_function: engineering, level: manager
    Sales Director       -> job_function: sales,       level: director
    Head of Design       -> job_function: design,      level: manager
    VP of Product        -> job_function: product,     level: vp

level — pick exactly one, based on SCOPE, not on the words in the title:
  junior    0-2 years, "junior", "associate", "entry level", intern
  mid       3-5 years, no seniority word in the title
  senior    "senior", or a clearly senior individual contributor
  staff     "staff", "principal", "distinguished" — an individual contributor
            ABOVE senior, with scope across teams, but WITHOUT direct reports
  lead      HAS DIRECT REPORTS or owns a team's delivery
  manager   "manager", "head of", manages a team
  director  "director", manages other managers
  vp        "VP", "chief", C-level
  unknown   the posting gives no reliable signal about seniority

  CRITICAL: a "Tech Lead" with no direct reports is senior or staff, NOT lead.
  An "Engineering Lead" who manages people is lead. The description decides,
  not the title.

  Use "unknown" honestly. A bare "Software Engineer" with no description is
  unknown, NOT mid. Only answer mid when the posting actually points there.

tags — zero or more, only from this list:
  backend, frontend, fullstack, mobile, infra, data, ml, ai, security, qa, sap, salesforce

  Three of these are easy to confuse:
    ml    training, fine-tuning or evaluating models; MLOps; data science pipelines
    ai    building on top of existing foundation models: prompting, RAG, agents,
          LLM-powered features inside a product
    data  data engineering, pipelines, warehouses, analytics, BI

  A role can carry both ml and ai when it genuinely does both. Management roles
  usually carry no tags at all. Leave tags empty when the posting gives you
  nothing to go on — do not guess.

suggested_tags — technologies or specialties that are clearly central to this
  posting but are NOT in the tag list above. Free text, lowercase, at most 3.
  Examples: terraform, kubernetes, shopify, blockchain, unity, servicenow
  Leave it empty when the list above already covers the posting. This field
  never reaches the filters — it only feeds a monthly review of what the
  taxonomy is missing.

eligible — true if a person living in Latin America could hold this job.
  false when the posting requires residence or work authorization in the US, Canada,
  the EU or any country outside Latin America, or requires on-site presence outside
  Latin America. When the posting says only "Remote" with no country restriction, true.

is_agency — true when the employer is a staffing, consulting, outsourcing or recruiting
  firm hiring on behalf of a client, rather than hiring for itself.

is_evergreen — true when this is a talent pool, "general interest" or "future
  opportunities" posting rather than a real open role.

note — ONE short sentence IN SPANISH explaining your call. Always explain when
  job_function is "other", and when the level was ambiguous. Maximum 160 characters.`;

const SCHEMA = {
  type: 'OBJECT',
  properties: {
    job_function:   { type: 'STRING', enum: ['engineering','product','design','marketing','sales','operations','support','other'] },
    level:          { type: 'STRING', enum: ['junior','mid','senior','staff','lead','manager','director','vp','unknown'] },
    tags:           { type: 'ARRAY', items: { type: 'STRING', enum: ['backend','frontend','fullstack','mobile','infra','data','ml','ai','security','qa','sap','salesforce'] } },
    suggested_tags: { type: 'ARRAY', items: { type: 'STRING' } },
    eligible:       { type: 'BOOLEAN' },
    is_agency:      { type: 'BOOLEAN' },
    is_evergreen:   { type: 'BOOLEAN' },
    note:           { type: 'STRING' },
  },
  required: ['job_function','level','tags','suggested_tags','eligible','is_agency','is_evergreen','note'],
  propertyOrdering: ['job_function','level','tags','suggested_tags','eligible','is_agency','is_evergreen','note'],
};

// ---------------------------------------------------------------------

const all    = $input.all();
const nuevos = all.filter(i => i.json.inserted === true);

const out = nuevos.map(i => {
  const j = i.json;

  const posting = [
    `TITLE: ${j.title || ''}`,
    `DEPARTMENT: ${j.department || '(none)'}`,
    `LOCATIONS: ${j.locations || '(none)'}`,
    `DESCRIPTION: ${j.description || '(none)'}`,
  ].join('\n');

  return { json: {
    db_id: j.id,
    external_id: j.external_id,
    title: j.title,
    model: MODEL,
    taxonomy_version: TAXONOMY_VERSION,
    body: {
      systemInstruction: { parts: [{ text: SYSTEM }] },
      contents: [{ role: 'user', parts: [{ text: posting }] }],
      generationConfig: {
        temperature: 0,
        responseMimeType: 'application/json',
        responseSchema: SCHEMA,
      },
    },
  }};
});

console.log('=== CLASIFICAR ===');
console.log('filas que devolvio Save jobs : ' + all.length);
console.log('nuevos (inserted = true)     : ' + out.length);
console.log('ejemplo de posting           :\n' +
  (out[0] ? out[0].json.body.contents[0].parts[0].text.slice(0, 600) : '(ninguno)'));

return out;
